extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_main_scene()
	if not check("basket_exists", basket != null, "La scena principale Basket si istanzia correttamente"):
		return

	var spawn_timer = get_prop(basket, "spawn_timer_node")
	if spawn_timer and spawn_timer.has_method("stop"):
		spawn_timer.stop()
	var wave_timer = get_prop(basket, "wave_timer")
	if wave_timer and wave_timer.has_method("stop"):
		wave_timer.stop()

	for child in basket.get_children():
		if child is Sprite2D and child.name != "Shadow" and child.name != "Handle":
			child.queue_free()

	var initial_lives = get_prop(basket, "lives", 3)
	check("initial_lives", initial_lives == 3, "Le vite iniziali devono essere 3 (trovate: %d)" % initial_lives)

	call_if_exists(basket, "take_damage", [1])
	await wait_frames(2)

	var lives_after_first = get_prop(basket, "lives", -1)
	var expected_after_first = initial_lives - 1
	check("lives_reduced", lives_after_first == expected_after_first, "Dopo il primo danno le vite scendono a %d (sono a %d)" % [expected_after_first, lives_after_first])

	var is_inv = get_prop(basket, "is_invulnerable", false)
	check("is_invulnerable_true", is_inv == true, "Dopo aver subito danno il cesto deve essere invulnerabile")

	var modulate_a = get_prop(basket, "modulate", Color.WHITE).a
	check("modulate_semi_transparent", modulate_a < 0.9, "Il cesto diventa semitrasparente (modulate.a è %.2f)" % modulate_a)

	await wait_seconds(0.5)
	call_if_exists(basket, "take_damage", [1])
	await wait_frames(2)
	var lives_during_inv = get_prop(basket, "lives", -1)
	check("damage_ignored", lives_during_inv == expected_after_first, "Un colpo subito durante l'invulnerabilità non deve togliere vite (vite: %d)" % lives_during_inv)

	await wait_seconds(0.6)
	var is_inv_after = get_prop(basket, "is_invulnerable", true)
	check("invulnerability_ended", is_inv_after == false, "Trascorsa l'attesa di 1 secondo l'invulnerabilità termina")

	var modulate_a_after = get_prop(basket, "modulate", Color.WHITE).a
	check("modulate_restored", absf(modulate_a_after - 1.0) < 0.05, "L'opacità modulate.a torna a 1.0 (è %.2f)" % modulate_a_after)
